mapper.select:
SELECT EXISTS (
  SELECT 1 FROM memory_recall_attempt a LEFT JOIN memory_active_attempt s
    ON s.owner_id=a.owner_id AND s.card_id=a.card_id AND s.attempt_id=a.id
  WHERE a.owner_id=#{owner}
  AND a.card_id=#{cardId}
  AND a.state IN ('THINKING','REVEALED') AND s.attempt_id IS NULL
) OR EXISTS (
  SELECT 1 FROM memory_active_attempt s JOIN memory_recall_attempt a
    ON a.owner_id=s.owner_id AND a.card_id=s.card_id AND a.id=s.attempt_id
  WHERE s.owner_id=#{owner}
  AND s.card_id=#{cardId}
  AND (a.state NOT IN ('THINKING','REVEALED') OR a.state<>s.attempt_state)
)

SELECT  FROM memory_active_attempt s
JOIN memory_recall_attempt a ON a.owner_id=s.owner_id AND a.card_id=s.card_id AND a.id=s.attempt_id
 WHERE s.owner_id=#{owner} AND s.card_id=#{cardId}

SELECT  FROM memory_active_attempt s
JOIN memory_recall_attempt a ON a.owner_id=s.owner_id AND a.card_id=s.card_id AND a.id=s.attempt_id
 WHERE s.owner_id=#{owner}
AND a.started_at <= #{asOf}
AND (a.started_at < #{cursor.time} OR (a.started_at=#{cursor.time} AND a.id < #{cursor.id}))
ORDER BY a.started_at DESC,a.id DESC LIMIT #{limit}

SELECT  FROM memory_recall_attempt a 
WHERE a.owner_id=#{owner} AND a.card_id=#{cardId}
AND a.sequence_number < #{before}
ORDER BY a.sequence_number DESC LIMIT #{limit}

SELECT sequence_number AS sequence,snapshot_json FROM memory_attempt_event WHERE owner_id=#{owner} AND attempt_id=#{id}
AND sequence_number < #{before}
ORDER BY sequence_number DESC LIMIT #{limit}

mapper.sql:
day_ratings AS (
  SELECT e.id,e.card_id,e.rate_basis_kind,e.attempt_sequence,
    ROW_NUMBER() OVER (PARTITION BY e.card_id ORDER BY e.attempt_sequence) AS day_position
  FROM memory_attempt_event e WHERE e.owner_id=#{owner} AND e.event_kind='RATE' AND e.count_regular=1
    AND e.occurred_at >= #{from} AND e.occurred_at < #{until}
)

mapper.select:
WHERE 1=1 AND recommended=1
AND (phase_rank > #{cursor.phaseRank} OR (phase_rank=#{cursor.phaseRank} AND effective_due_at > #{cursor.dueAt}) OR (phase_rank=#{cursor.phaseRank} AND effective_due_at=#{cursor.dueAt} AND card_id > #{cursor.cardId}))
ORDER BY phase_rank,effective_due_at,card_id LIMIT #{limit}

SELECT id,title,start_date,end_date,zone_id,card_count,created_at FROM memory_cram_batch WHERE owner_id=#{owner}
AND (created_at < #{cursor.time} OR (created_at=#{cursor.time} AND id < #{cursor.id}))
ORDER BY created_at DESC,id DESC LIMIT #{limit}
